const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const boston = ee.Geometry.Point([-71.0589, 42.3601]); // Approximate center of Boston, MA
  const startDate = '2019-01-29';
  const endDate = '2019-02-05'; // Inclusive

  // Define a function to convert Kelvin to Celsius
  const toCelsius = (image) => {
    return image.subtract(273.15).copyProperties(image, ['system:time_start']);
  };

  // 2. Data Acquisition
  let collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, ee.Date(endDate).advance(1, 'day')) // Filter to include end date
    .filterBounds(boston)
    .select('temperature_2m')
    .map(toCelsius);

  // Check if the collection is empty
  const initialCollectionSize = await collection.size().getInfo();
  if (initialCollectionSize === 0) {
    console.log("No ERA5-Land Hourly data found for the specified period and location.");
    console.log("C1");
    return;
  }
  console.log(`Total hourly images: ${initialCollectionSize}`);

  // 3. Processing: Calculate daily maximum temperature
  const dailyMaxTemperatures = ee.List.sequence(0, ee.Date(endDate).difference(ee.Date(startDate), 'day'))
    .map((dayOffset) => {
      const currentDay = ee.Date(startDate).advance(dayOffset, 'day');
      const nextDay = currentDay.advance(1, 'day');

      const dailyCollection = collection.filterDate(currentDay, nextDay);

      // Aggregate max temperature for the current day
      // Use reduceRegion on the mosaic of the daily collection
      const dailyMax = dailyCollection.max()
        .reduceRegion({
          reducer: ee.Reducer.max(),
          geometry: boston,
          scale: 11132, // ERA5-Land resolution is ~9km, using a conservative scale
          maxPixels: 1e9
        })
        .get('temperature_2m'); // Get the value for the 'temperature_2m' band

      return dailyMax;
    });

  const dailyMaxTempsList = await dailyMaxTemperatures.getInfo();

  // Filter out any null values (e.g., if a day had no valid data)
  const validDailyMaxTemps = dailyMaxTempsList.filter(temp => typeof temp === 'number' && !isNaN(temp));

  if (validDailyMaxTemps.length === 0) {
    console.log("No valid daily maximum temperature pixels found after processing for the period.");
    console.log("C2");
    return;
  }
  console.log(`Valid daily max temperatures processed: ${validDailyMaxTemps.length}`);
  console.log(`Daily max temperatures (C): ${validDailyMaxTemps.map(t => t.toFixed(2)).join(', ')}`);


  // 4. Calculation: Find overall max and min daily temps and their difference
  const overallMaxDailyTemp = Math.max(...validDailyMaxTemps);
  const overallMinDailyTemp = Math.min(...validDailyMaxTemps);

  if (overallMaxDailyTemp === -Infinity || overallMinDailyTemp === Infinity) {
    console.log("Could not determine overall max or min daily temperatures.");
    console.log("C3");
    return;
  }

  const temperatureDifference = overallMaxDailyTemp - overallMinDailyTemp;

  // 5. Validation & Final Answer
  console.log(`Overall highest daily max temperature: ${overallMaxDailyTemp.toFixed(2)} C`);
  console.log(`Overall lowest daily max temperature: ${overallMinDailyTemp.toFixed(2)} C`);
  console.log(`Temperature difference: ${temperatureDifference.toFixed(2)} C`);

  if (temperatureDifference >= 30) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
